        You will be provided with a patch used to fix a bug. 
        Based on the commit message and modifications in the patch, you need to analyze the root cause of the bug in detail. 

        Here is the patch content:
        From bc05cd99b1f8091dce8d5861bcc65cf05443bc64 Mon Sep 17 00:00:00 2001
From: "Gary E. Miller" <gem@rellim.com>
Date: Tue, 3 Mar 2020 13:30:05 -0800
Subject: [PATCH] Change nanowait() to use timespec.

This fixes the fix in commit 8c29500cd1e90281bb308894eda4989079ac5142
and resolves issue #58.
---
 driver_geostar.c | 13 ++++++++++---
 driver_tsip.c    |  7 ++++++-
 gps2udp.c        |  5 ++++-
 gpsutils.c       | 10 +++++-----
 libgps_sock.c    |  9 ++++++---
 timespec.h       |  2 +-
 6 files changed, 32 insertions(+), 14 deletions(-)

diff --git a/driver_geostar.c b/driver_geostar.c
index a011fda22..ff6b3eccf 100644
--- a/driver_geostar.c
+++ b/driver_geostar.c
@@ -12,13 +12,13 @@

 #include "gpsd_config.h"  /* must be before all includes */

+#include <math.h>
 #include <stdbool.h>
 #include <stdio.h>
-#include <math.h>
 #include <string.h>

-#include "gpsd.h"
 #include "bits.h"
+#include "gpsd.h"
 #include "strfuncs.h"
 #include "timespec.h"

@@ -93,8 +93,13 @@ static bool geostar_detect(struct gps_device_t *session)
     putbe32(buf, 0, 0);
     if (geostar_write(session, 0xc1, buf, 1) == 0) {
 	unsigned int n;
+        struct timespec to;
+        // FIXME: this holds the main loop from running...
 	for (n = 0; n < 3; n++) {
-	    if (!nanowait(myfd, NS_IN_SEC))
+            // wait one second
+            to.tv_sec = 1;
+            to.tv_nsec = 0;
+	    if (!nanowait(myfd, &to))
 		break;
 	    if (generic_get(session) >= 0) {
 		if (session->lexer.type == GEOSTAR_PACKET) {
@@ -629,3 +634,5 @@ const struct gps_type_t driver_geostar =
 /* *INDENT-ON* */

 #endif /* GEOSTAR_ENABLE */
+
+// vim: set expandtab shiftwidth=4
diff --git a/driver_tsip.c b/driver_tsip.c
index 1c72e21f3..6cf253d90 100644
--- a/driver_tsip.c
+++ b/driver_tsip.c
@@ -205,8 +205,13 @@ static bool tsip_detect(struct gps_device_t *session)
     myfd = session->gpsdata.gps_fd;
     if (write(myfd, buf, 4) == 4) {
         unsigned int n;
+        struct timespec to;
+        // FIXME: this holds the main loop from running...
         for (n = 0; n < 3; n++) {
-            if (!nanowait(myfd, NS_IN_SEC))
+            // wait one second
+            to.tv_sec = 1;
+            to.tv_nsec = 0;
+            if (!nanowait(myfd, &to))
                 break;
             if (generic_get(session) >= 0) {
                 if (session->lexer.type == TSIP_PACKET) {
diff --git a/gps2udp.c b/gps2udp.c
index 571f277d0..ec928c162 100644
--- a/gps2udp.c
+++ b/gps2udp.c
@@ -237,6 +237,7 @@ static ssize_t read_gpsd(char *message, size_t len)
     int ind;
     char c;
     int retry=0;
+    struct timespec to;

     /* allow room for trailing NUL */
     len--;
@@ -244,7 +245,9 @@ static ssize_t read_gpsd(char *message, size_t len)
     /* loop until we get some data or an error */
     for (ind = 0; ind < (int)len;) {
         /* prepare for a blocking read with a 10s timeout */
-        int result = nanowait(gpsdata.gps_fd, 10 * NS_IN_SEC);
+        to.tv_sec = 10;
+        to.tv_nsec = 0;
+        int result = nanowait(gpsdata.gps_fd, &to);

         switch (result)
         {
diff --git a/gpsutils.c b/gpsutils.c
index 315330b44..aefab2feb 100644
--- a/gpsutils.c
+++ b/gpsutils.c
@@ -731,16 +731,16 @@ double earth_distance(double lat1, double lon1, double lat2, double lon2)
 	return earth_distance_and_bearings(lat1, lon1, lat2, lon2, NULL, NULL);
 }

-bool nanowait(int fd, int nanoseconds)
+// Wait for data until timeout, ignoring signals.
+bool nanowait(int fd, struct timespec *to)
 {
     fd_set fdset;
-    struct timespec to;

     FD_ZERO(&fdset);
     FD_SET(fd, &fdset);
-    to.tv_sec = nanoseconds / NS_IN_SEC;
-    to.tv_nsec = nanoseconds % NS_IN_SEC;
-    return pselect(fd + 1, &fdset, NULL, NULL, &to, NULL) == 1;
+    TS_NORM(to);         // just in case
+    // sigmask is NULL, so equivalent to select()
+    return pselect(fd + 1, &fdset, NULL, NULL, to, NULL) == 1;
 }

 /* Accept a datum code, return matching string
diff --git a/libgps_sock.c b/libgps_sock.c
index 74619c16d..a86efb5e7 100644
--- a/libgps_sock.c
+++ b/libgps_sock.c
@@ -129,18 +129,21 @@ int gps_sock_open(const char *host, const char *port,
     return 0;
 }

-bool gps_sock_waiting(const struct gps_data_t *gpsdata, int timeout)
 /* is there input waiting from the GPS? */
-/* timeout is in uSec */
+/* timeout is in milli Seconds */
+bool gps_sock_waiting(const struct gps_data_t *gpsdata, int timeout)
 {
 #ifndef USE_QT
+    struct timespec to;
+
     libgps_debug_trace((DEBUG_CALLS, "gps_waiting(%d): %d\n",
                        timeout, PRIVATE(gpsdata)->waitcount++));
     if (PRIVATE(gpsdata)->waiting > 0)
 	return true;

+    MSTOTS(&to, timeout);
     /* all error conditions return "not waiting" -- crude but effective */
-    return nanowait(gpsdata->gps_fd, timeout * 1000);
+    return nanowait(gpsdata->gps_fd, &to);
 #else
     return ((QTcpSocket *) (gpsdata->gps_fd))->waitForReadyRead(timeout / 1000);
 #endif
diff --git a/timespec.h b/timespec.h
index aca79a7c5..d71f77d81 100644
--- a/timespec.h
+++ b/timespec.h
@@ -151,7 +151,7 @@ static inline void TS_NORM( struct timespec *ts)

 extern const char *timespec_str(const struct timespec *, char *, size_t);

-bool nanowait(int, int);
+bool nanowait(int, struct timespec *);

 #endif /* GPSD_TIMESPEC_H */

-- 
